data.script:
function check(v,m){if(!v)throw Error(m);}
const selected=app.currentWindow.selectedDrafts;
check(selected.length===2,'two selected rows');
check(selected[0].title==='Picker QA: Zulu'&&selected[1].title==='Picker QA: Excluded','visible row order');
check(selected.every(d=>d instanceof Draft),'typed rows');
check(selected[0]===Draft.find(selected[0].uuid),'shared identity');
selected.pop();
check(app.currentWindow.selectedDrafts.length===2,'independent array');
check(draft.title==='Picker QA: Alpha'&&editor.getText().startsWith('Picker QA: Alpha'),'current draft stays Alpha');
console.log('Two selected rows; Alpha editor preserved');
const workspace=app.currentWindow.currentWorkspace;
check(workspace instanceof Workspace&&workspace.loadFolder==='inbox','typed current workspace');
check(workspace.queryString==='','current list query');workspace.queryString='Detached only';
check(app.currentWindow.currentWorkspace.queryString==='','snapshot does not apply');
console.log('Current workspace snapshot detached');

if(app.currentWindow.selectedDrafts.length!==0)throw Error('Expected no selected rows');
if(draft.title!=='Picker QA: Alpha')throw Error('Current draft changed');
console.log('Empty list selection; Alpha editor preserved');
